/* WARNING: Script requires that SQLITE_DBCONFIG_DEFENSIVE be disabled */
PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE Namespace (
    id INTEGER PRIMARY KEY , 
    name TEXT NOT NULL UNIQUE, 
    description TEXT
);
CREATE TABLE Tags (
    id INTEGER PRIMARY KEY , 
    name TEXT NOT NULL, 
    namespace INTEGER NOT NULL, 
    count INTEGER NOT NULL DEFAULT 0, 

    UNIQUE(name, namespace), 

    FOREIGN KEY (namespace) REFERENCES Namespace(id) ON DELETE CASCADE ON UPDATE CASCADE
);
PRAGMA writable_schema=ON;
    name,
    namespace UNINDEXED,
    content=''High_Value_Tags'',
    content_rowid=''id'',
    tokenize = ''trigram'' 
)');
CREATE TABLE IF NOT EXISTS 'Tags_Popular_fts_data'(id INTEGER PRIMARY KEY, block BLOB);
CREATE TABLE IF NOT EXISTS 'Tags_Popular_fts_idx'(segid, term, pgno, PRIMARY KEY(segid, term)) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS 'Tags_Popular_fts_docsize'(id INTEGER PRIMARY KEY, sz BLOB);
CREATE TABLE IF NOT EXISTS 'Tags_Popular_fts_config'(k PRIMARY KEY, v) WITHOUT ROWID;
CREATE TABLE Relationship (
    file_id INTEGER NOT NULL,
    tag_id  INTEGER NOT NULL,

    PRIMARY KEY (file_id, tag_id),

    FOREIGN KEY (file_id)
        REFERENCES File(id)
        ON DELETE CASCADE
        ON UPDATE CASCADE,

    FOREIGN KEY (tag_id)
        REFERENCES Tags(id)
        ON DELETE CASCADE
        ON UPDATE CASCADE
) WITHOUT ROWID;
CREATE TABLE Parents (
id INTEGER PRIMARY KEY AUTOINCREMENT,
    tag_id INTEGER NOT NULL,
    relate_tag_id INTEGER NOT NULL,
    limit_to INTEGER,

    FOREIGN KEY (tag_id) REFERENCES Tags(id) ON DELETE CASCADE ON UPDATE CASCADE,
    FOREIGN KEY (relate_tag_id) REFERENCES Tags(id) ON DELETE CASCADE ON UPDATE CASCADE,
    FOREIGN KEY (limit_to) REFERENCES Tags(id) ON DELETE SET NULL ON UPDATE CASCADE,

    CHECK (tag_id != relate_tag_id),

    UNIQUE(tag_id, relate_tag_id, limit_to)
);
CREATE TABLE Settings (
    name TEXT PRIMARY KEY,
    description TEXT, 
    num INTEGER, 
    param TEXT
);
CREATE TABLE FileStorageLocations (id INTEGER PRIMARY KEY , location TEXT NOT NULL UNIQUE);
CREATE TABLE File 
            (id INTEGER PRIMARY KEY  NOT NULL, 
            hash TEXT UNIQUE, 
            extension TEXT, 
            storage_id INTEGER, 

            CHECK (
                (hash IS NOT NULL AND extension IS NOT NULL) OR
                (hash IS NULL AND extension IS NULL)
            ),

            FOREIGN KEY (storage_id) REFERENCES FileStorageLocations(id) ON DELETE CASCADE ON UPDATE CASCADE
            );
CREATE TABLE Jobs (
    id INTEGER PRIMARY KEY  NOT NULL, 
    time INTEGER NOT NULL, 
    reptime INTEGER NOT NULL, 
    priority INTEGER NOT NULL,  
    is_running BOOL NOT NULL DEFAULT False,
    recreation TEXT NOT NULL, 
    site TEXT NOT NULL, 
    param TEXT NOT NULL, 
    user_data TEXT NOT NULL
);
CREATE TABLE RelationshipRoaringFileid (
    fileid INTEGER PRIMARY KEY,
    tagid_bitmap BLOB NOT NULL
) WITHOUT ROWID;
CREATE TABLE RelationshipRoaringTagid (
    tagid  INTEGER  PRIMARY KEY,
    fileid_bitmap BLOB NOT NULL
) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS sqlite_sequence(name,seq);
DELETE FROM sqlite_sequence;
CREATE VIEW High_Value_Tags AS 
    SELECT id, name, namespace 
    FROM Tags 
    WHERE count >= 5;
CREATE TRIGGER tags_ai AFTER INSERT ON Tags 
WHEN new.count = 5
BEGIN
    VALUES (new.id, new.name, new.namespace);
END;
CREATE TRIGGER tags_ad AFTER DELETE ON Tags 
WHEN old.count >= 5
BEGIN
    VALUES('delete', old.id, old.name, old.namespace);
END;
CREATE TRIGGER relationship_insert_count
AFTER INSERT ON Relationship
BEGIN
    UPDATE Tags
    SET count = count + 1
    WHERE id = NEW.tag_id;
END;
CREATE TRIGGER relationship_delete_count
AFTER DELETE ON Relationship
BEGIN
    UPDATE Tags
    SET count = count - 1
    WHERE id = OLD.tag_id;
END;
CREATE INDEX idx_namespace ON Namespace (name);
CREATE INDEX idx_tags_count_covering ON Tags(count DESC, name, namespace);
CREATE INDEX idx_tag_id_file_id ON Relationship(tag_id, file_id DESC);
CREATE INDEX idx_parents_lim ON Parents (limit_to);
CREATE INDEX idx_parents_rel ON Parents (relate_tag_id);
CREATE UNIQUE INDEX idx_unique_parents_null_safe ON Parents (tag_id, relate_tag_id, IFNULL(limit_to, -1));
CREATE INDEX idx_file_hash ON File (hash);
CREATE UNIQUE INDEX idx_jobs_dedup 
ON Jobs (time, reptime, site, param);
PRAGMA writable_schema=OFF;
COMMIT;
